<?php
require_once __DIR__.'/config/database.php'; require_once __DIR__.'/includes/functions.php'; require_role(['admin']); verify_csrf();
if($_SERVER['REQUEST_METHOD']==='POST'){$name=trim($_POST['name']??'');$email=trim($_POST['email']??'');$role=$_POST['role']??'staff';$password=$_POST['password']??'';$cid=($_POST['customer_id']??'')!==''?(int)$_POST['customer_id']:null;if($name===''||!filter_var($email,FILTER_VALIDATE_EMAIL)||strlen($password)<8||!in_array($role,['admin','staff','customer'],true)||($role==='customer'&&!$cid)){flash('error','Provide a name, valid email, password of at least 8 characters, and customer account for customer users.');redirect('users.php');}try{$s=$pdo->prepare("INSERT INTO users(name,email,password_hash,role,customer_id) VALUES(?,?,?,?,?)");$s->execute([$name,$email,password_hash($password,PASSWORD_DEFAULT),$role,$cid]);audit($pdo,'CREATE USER',$email);flash('success','User account created.');}catch(PDOException $e){flash('error','Could not create user. Email or customer portal account may already be in use.');}redirect('users.php');}
$customers=$pdo->query("SELECT id,account_number,full_name FROM customers WHERE id NOT IN (SELECT customer_id FROM users WHERE customer_id IS NOT NULL) ORDER BY full_name")->fetchAll();$rows=$pdo->query("SELECT u.id,u.name,u.email,u.role,u.status,u.created_at,c.account_number FROM users u LEFT JOIN customers c ON c.id=u.customer_id ORDER BY u.created_at DESC")->fetchAll();$pageTitle='System users';require 'includes/header.php';
?>
<div class="two-col"><div class="panel"><h3>Create a user</h3><form method="post" class="stack-form"><input type="hidden" name="csrf" value="<?=e(csrf_token())?>"><label>Full name *</label><input name="name" required><label>Email *</label><input type="email" name="email" required><label>Temporary password *</label><input type="password" name="password" minlength="8" required><label>Role *</label><select name="role" id="user-role"><option value="staff">Staff</option><option value="admin">Administrator</option><option value="customer">Customer portal</option></select><div id="customer-choice" hidden><label>Link customer account *</label><select name="customer_id"><option value="">Select account</option><?php foreach($customers as $c):?><option value="<?=$c['id']?>"><?=e($c['account_number'].' · '.$c['full_name'])?></option><?php endforeach;?></select></div><button class="btn primary">Create user</button></form></div><div class="panel"><h3>Access roles</h3><ul class="feature-list"><li><b>Administrator:</b> full system administration and settings.</li><li><b>Staff:</b> customer, reading, billing, payment and complaint operations.</li><li><b>Customer:</b> own bills, payments, notifications and complaints.</li></ul><div class="note-box">Create customer records first, then create a customer portal login linked to that account.</div></div></div>
<div class="panel"><h3>Registered system users</h3><table><thead><tr><th>Name</th><th>Email</th><th>Role</th><th>Customer account</th><th>Status</th><th>Created</th></tr></thead><tbody><?php foreach($rows as $r):?><tr><td><?=e($r['name'])?></td><td><?=e($r['email'])?></td><td><?=e(ucfirst($r['role']))?></td><td><?=e($r['account_number']??'—')?></td><td><?=e(ucfirst($r['status']))?></td><td><?=e($r['created_at'])?></td></tr><?php endforeach;?></tbody></table></div>
<script>document.addEventListener('DOMContentLoaded',()=>{const r=document.getElementById('user-role'),c=document.getElementById('customer-choice');if(r&&c){const f=()=>c.hidden=r.value!=='customer';r.addEventListener('change',f);f();}});</script>
<?php require 'includes/footer.php';?>
